import requests
import json
import time
import os
import re
import uuid
from datetime import datetime

# --- CONFIGURATION ---
CHEAP_MODEL = "llama3.2:latest"
DEEP_MODEL = "llama3:latest"
OLLAMA_URL = "http://localhost:11434/api/generate"
DATASET_PATH = "revision/data/pilot_dataset_mini.json"
RESULTS_ROOT = "revision/results"
SCHEMA_VERSION = "1.1"

class BenchmarkEngine:
    def __init__(self, experiment_id=None):
        if experiment_id is None:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            self.experiment_id = f"exp_{timestamp}_{uuid.uuid4().hex[:6]}"
        else:
            self.experiment_id = experiment_id
            
        self.exp_dir = os.path.join(RESULTS_ROOT, self.experiment_id)
        
        if os.path.exists(self.exp_dir):
            raise FileExistsError(f"Experiment directory {self.exp_dir} already exists.")
        
        os.makedirs(self.exp_dir, exist_ok=True)
        self.lock_file = os.path.join(self.exp_dir, ".lock")
        
        # Open lock file to prevent simultaneous runs
        self.lock_handle = open(self.lock_file, 'w')
        self.lock_handle.write(f"PID: {os.getpid()}")

    def __del__(self):
        if hasattr(self, 'lock_handle'):
            self.lock_handle.close()
            try: os.remove(self.lock_file)
            except: pass

    def call_ollama(self, model, prompt, timeout=600):
        payload = {"model": model, "prompt": prompt, "stream": False, "options": {"temperature": 0}}
        try:
            start = time.perf_counter()
            response = requests.post(OLLAMA_URL, json=payload, timeout=timeout)
            latency = (time.perf_counter() - start) * 1000
            if response.status_code != 200:
                return f"ERROR: {response.status_code}", latency, "error"
            return response.json().get('response', '').strip(), latency, "completed"
        except requests.exceptions.Timeout:
            return "TIMEOUT", 0, "timeout"
        except Exception as e:
            return f"ERROR: {e}", 0, "error"

